<script setup lang="ts">
import {ref,watch,onUnmounted} from 'vue';
import {item,type CustomerRenewalEligibility} from '@papilio/api';
import {toman,faDate} from '@papilio/ui';
const props=defineProps<{subscriptionId:number;refreshKey?:boolean}>();
const value=ref<CustomerRenewalEligibility|null>(null);const busy=ref(false);const error=ref('');let sequence=0;
const reasons:Record<string,string>={trial_not_renewable:'Trials cannot renew automatically.',subscription_not_renewable:'This service state cannot renew.',customer_renewals_disabled:'Renewal access is disabled for this account.',payer_renewals_disabled:'Renewal access is disabled for the payer.',renewal_quote_unavailable:'A renewal quote is unavailable under the current plan rules.'};
async function load():Promise<void>{const stamp=++sequence;busy.value=true;value.value=null;error.value='';try{const result=await item<CustomerRenewalEligibility>(`/v1/customer/subscriptions/${props.subscriptionId}/renewal-eligibility`);if(stamp===sequence)value.value=result;}catch(cause){if(stamp===sequence)error.value=cause instanceof Error?cause.message:'Could not check renewal.';}finally{if(stamp===sequence)busy.value=false;}}
watch(()=>[props.subscriptionId,props.refreshKey],()=>{void load();},{immediate:true});onUnmounted(()=>{sequence++;});
</script>
<template><section class="hint-box stack" aria-label="Service renewal eligibility"><h4>Renewal readiness</h4><p v-if="busy">Checking current renewal rules…</p><p v-if="error" class="message error" role="alert">{{error}}</p><template v-if="value"><p>Checked: {{faDate(value.checked_at)}}</p><p>{{value.eligible?'Renewal is eligible under current rules.':reasons[value.reason_code??'']??'Renewal is currently unavailable.'}}</p><p>Current renewal price: {{value.renewal_price_rial===null?'Unavailable':toman(value.renewal_price_rial)}}</p><template v-if="value.payer_kind==='self'"><p>My wallet: {{value.wallet_balance_rial===null?'Unavailable':toman(value.wallet_balance_rial)}}</p><p v-if="value.wallet_shortfall_rial!==null">Wallet shortfall: {{toman(value.wallet_shortfall_rial)}}</p></template><p v-else>Another payer funds this service. Their wallet details are private.</p><p>{{value.renewal_due?'The configured renewal trigger has been reached.':'The configured renewal trigger has not been reached.'}}</p><p>{{value.auto_renew_authorized?'Automatic renewal is authorized.':'Automatic renewal is not authorized.'}} Eligibility and funds do not confirm execution. Follow the service status after the scheduled check.</p></template><button class="btn secondary" type="button" :disabled="busy" @click="load">Refresh renewal readiness</button></section></template>
